"""Ideas are generated by a worker job: queue it through the API, run it here, return what it made."""

from sqlalchemy import select

from clipper import worker
from clipper.db import session_scope
from clipper.db.models import Idea, Job


def generate(client, **body) -> list[dict]:
    with session_scope() as db:
        before = db.scalar(select(Idea.id).order_by(Idea.id.desc()).limit(1)) or 0
    answer = client.post("/api/v1/ideas/generate", json=body)
    assert answer.status_code == 202, answer.text
    job = answer.json()
    assert job["kind"] == "ideas"
    worker.run_job(job["id"])
    with session_scope() as db:
        state = db.get(Job, job["id"])
        assert state.state == "succeeded", state.error
    return [i for i in sorted(client.get("/api/v1/ideas").json(), key=lambda i: i["id"]) if i["id"] > before]
